.uv-if {
  --c1: #0071e3;
  --c2: #8ec5ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-if {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  position: relative;
  display: block;
  width: 16em;
  font-size: var(--s);
}

.uv-if input {
  width: 100%;
  box-sizing: border-box;
  height: 3.4em;
  padding: 1.2em 1em .4em;
  border: 0;
  border-radius: .9em;
  font: inherit;
  color: var(--fg);
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  outline: none;
  box-shadow: inset 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent);
  transition: box-shadow calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-if span {
  position: absolute;
  left: 1em;
  top: 50%;
  color: color-mix(in srgb,var(--fg) 50%,transparent);
  translate: 0 -50%;
  transform-origin: left;
  pointer-events: none;
  transition: all calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-if input:focus {
  box-shadow: inset 0 0 0 2px var(--c1),0 0 0 4px color-mix(in srgb,var(--c1) 18%,transparent);
}

.uv-if input:focus+span,.uv-if input:not(:placeholder-shown)+span {
  top: .95em;
  transform: scale(.75);
  color: var(--c1);
}

