.uv-iai {
  --c1: #7c5cff;
  --c2: #22d3ee;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

@property --uv-iai {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}

.uv-iai {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 20em;
  padding: .9em;
  border-radius: 1.4em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent),0 14px 34px -24px rgba(0,0,0,.45);
  isolation: isolate;
}

.uv-iai::before {
  content: "";
  position: absolute;
  inset: -1.5px;
  z-index: -1;
  border-radius: inherit;
  padding: 1.5px;
  background: conic-gradient(from var(--uv-iai),var(--c1),var(--c2),transparent 40%,var(--c1));
  -webkit-mask: linear-gradient(#000 0 0) content-box,linear-gradient(#000 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  opacity: 0;
  transition: opacity calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
  animation: uv-iai calc(3s / var(--k)) linear infinite;
}

.uv-iai::after {
  content: "";
  position: absolute;
  inset: 20% 10% -10%;
  z-index: -2;
  border-radius: 50%;
  background: linear-gradient(90deg,var(--c1),var(--c2));
  filter: blur(2em);
  opacity: 0;
  transition: opacity calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-iai:focus-within::before {
  opacity: 1;
}

.uv-iai:focus-within::after {
  opacity: .35;
}

.uv-iai .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.uv-iai .bx {
  display: block;
}

.uv-iai textarea {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  font: inherit;
  color: var(--fg);
  display: block;
  width: 100%;
  max-height: 8em;
  resize: none;
  line-height: 1.45;
  padding: .1em .2em;
}

.uv-iai textarea::placeholder {
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-iai .rw {
  display: flex;
  align-items: center;
  gap: .35em;
  margin-top: .7em;
}

.uv-iai .ch {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: .4em .75em;
  border-radius: 2em;
  font-size: .78em;
  font-weight: 600;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  transition: all calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-iai .ch:hover {
  color: var(--fg);
  background: color-mix(in srgb,var(--c1) 14%,transparent);
}

.uv-iai .go {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: grid;
  place-items: center;
  width: 2.2em;
  height: 2.2em;
  margin-left: auto;
  border-radius: 50%;
  color: #fff;
  background: color-mix(in srgb,var(--fg) 25%,transparent);
  transition: background calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1),transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-iai .go svg {
  width: 1.1em;
  height: 1.1em;
}

.uv-iai:has(textarea:not(:placeholder-shown)) .go {
  background: linear-gradient(135deg,var(--c1),var(--c2));
  transform: rotate(0) scale(1.05);
}

.uv-iai .go:active {
  transform: scale(.9);
}

.uv-iai button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

@keyframes uv-iai {
  to {
    --uv-iai: 360deg;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-iai,.uv-iai *,.uv-iai *::before,.uv-iai *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

