document.querySelectorAll(".uv-ich").forEach(el => {
  const p=el.querySelector("input[type=color]"),h=el.querySelector(".hx");const set=c=>{el.style.setProperty("--pick",c);p.value=c;h.value=c.slice(1).toUpperCase();el.classList.remove("bad")};
p.addEventListener("input",()=>set(p.value));
h.addEventListener("input",()=>{const v=h.value.replace(/[^0-9a-f]/gi,"").slice(0,6);h.value=v.toUpperCase();if(v.length===6)set("#"+v.toLowerCase());el.classList.toggle("bad",v.length>0&&v.length!==6&&v.length!==3)});
el.querySelectorAll(".rc button").forEach(b=>b.addEventListener("click",()=>set(b.style.getPropertyValue("--c").trim())));set(p.value)
});

