.uv-ifd {
  --c1: #2563eb;
  --c2: #dbeafe;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-ifd {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 18em;
}

.uv-ifd .dz {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: .35em;
  padding: 1.4em 1em;
  border-radius: 1.2em;
  text-align: center;
  cursor: pointer;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  outline: 2px dashed color-mix(in srgb,var(--fg) 20%,transparent);
  outline-offset: -2px;
  transition: all calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ifd input {
  position: absolute;
  inset: 0;
  opacity: 0;
  cursor: pointer;
}

.uv-ifd .ic {
  display: grid;
  place-items: center;
  width: 2.8em;
  height: 2.8em;
  margin-bottom: .3em;
  border-radius: 50%;
  color: var(--c1);
  background: var(--c2);
  transition: transform calc(0.4s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uv-ifd .ic svg {
  width: 1.4em;
  height: 1.4em;
}

.uv-ifd b {
  font-size: .95em;
}

.uv-ifd .or {
  font-size: .82em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ifd .or u {
  color: var(--c1);
  text-underline-offset: .2em;
}

.uv-ifd .hn {
  font-size: .7em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ifd .dz:hover .ic {
  transform: translateY(-.2em);
}

.uv-ifd .dz:has(input:focus-visible) {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-ifd.is-over .dz {
  background: var(--c2);
  outline-color: var(--c1);
  transform: scale(1.02);
}

.uv-ifd.is-over .ic {
  animation: uv-ifd calc(0.8s / var(--k)) ease-in-out infinite;
  color: #fff;
  background: var(--c1);
}

.uv-ifd ul {
  list-style: none;
  margin: .6em 0 0;
  padding: 0;
  display: grid;
  gap: .4em;
}

.uv-ifd li {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: .3em .6em;
  align-items: center;
  padding: .6em .8em;
  border-radius: .8em;
  font-size: .82em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent),0 14px 34px -24px rgba(0,0,0,.45);
  animation: uv-ifd-in calc(0.35s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uv-ifd li span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 600;
}

.uv-ifd li em {
  font-style: normal;
  font-variant-numeric: tabular-nums;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ifd li i {
  grid-column: 1/-1;
  height: .3em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  overflow: hidden;
}

.uv-ifd li i::after {
  content: "";
  display: block;
  height: 100%;
  width: var(--p,0%);
  border-radius: inherit;
  background: var(--c1);
  transition: width .2s linear;
}

.uv-ifd li.ok em {
  color: var(--c1);
  font-weight: 700;
}

@keyframes uv-ifd {
  50% {
    transform: translateY(-.25em);
  }
}

@keyframes uv-ifd-in {
  from {
    opacity: 0;
    transform: translateY(.4em);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-ifd,.uv-ifd *,.uv-ifd *::before,.uv-ifd *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

