  /* tamaño */
  --k: 1;
  /* velocidad */
  --mx: 120;
  /* máximo */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-isc {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 16em;
  --v: 24;
  --max: 120;
}

.uv-isc .rw {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: .6em;
}

.uv-isc .hd {
  display: flex;
  align-items: center;
  gap: .4em;
  padding: .4em .6em;
  border-radius: .6em;
  font-weight: 650;
  cursor: ew-resize;
  user-select: none;
  touch-action: none;
  transition: background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),color calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-isc .hd svg {
  width: 1em;
  height: 1em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1),color calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-isc .hd:hover,.uv-isc.is-drag .hd {
  background: var(--c2);
  color: var(--c1);
}

.uv-isc .hd:hover svg,.uv-isc.is-drag .hd svg {
  color: var(--c1);
  transform: scaleX(1.25);
}

.uv-isc .fd {
  display: flex;
  align-items: center;
  width: 6em;
  padding: 0 .7em;
  border-radius: .7em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent),0 14px 34px -24px rgba(0,0,0,.45);
}

.uv-isc .fd:focus-within {
  box-shadow: 0 0 0 2px var(--c1),0 0 0 6px color-mix(in srgb,var(--c1) 18%,transparent),0 14px 34px -24px rgba(0,0,0,.45);
}

.uv-isc input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  font: inherit;
  color: var(--fg);
  height: 2.3em;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  -moz-appearance: textfield;
}

.uv-isc input::-webkit-inner-spin-button {
  -webkit-appearance: none;
}

.uv-isc .un {
  font-size: .8em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-isc .rl {
  position: relative;
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  height: 1.2em;
  margin: .9em .3em 0;
}

.uv-isc .rl b {
  width: 1px;
  height: .45em;
  background: color-mix(in srgb,var(--fg) 25%,transparent);
}

.uv-isc .rl b.lg {
  height: .9em;
}

.uv-isc .bar {
  position: absolute;
  left: 0;
  bottom: 0;
  height: 3px;
  width: calc(var(--v) / var(--max) * 100%);
  border-radius: 2px;
  background: var(--c1);
  transition: width .08s linear;
}

.uv-isc .pv {
  width: 5em;
  height: 3.4em;
  margin: 1em auto 0;
  border-radius: calc(var(--v) / var(--max) * 1.7em);
  background: linear-gradient(135deg,var(--c1),color-mix(in srgb,var(--c1) 50%,#fff));
  box-shadow: 0 .6em 1.2em -.6em var(--c1);
  transition: border-radius .08s linear;
}

