.uv-ivo {
  --c1: #ef4444;
  --c2: #fee2e2;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uv-ivo {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: .5em;
  width: 18em;
}

.uv-ivo .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.uv-ivo .fd {
  position: relative;
  display: flex;
  align-items: center;
  gap: .5em;
  padding: 0 .9em;
  border-radius: 2em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent),0 14px 34px -24px rgba(0,0,0,.45);
  transition: box-shadow calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ivo .fd:focus-within {
  box-shadow: 0 0 0 2px var(--c1),0 0 0 6px color-mix(in srgb,var(--c1) 18%,transparent),0 14px 34px -24px rgba(0,0,0,.45);
}

.uv-ivo .fd>svg {
  width: 1.1em;
  height: 1.1em;
  flex: none;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ivo input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  font: inherit;
  color: var(--fg);
  height: 2.9em;
}

.uv-ivo input::placeholder {
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uv-ivo .wv {
  position: absolute;
  right: .9em;
  top: 50%;
  display: flex;
  align-items: center;
  gap: .14em;
  height: 1.4em;
  translate: 0 -50%;
  opacity: 0;
  transition: opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ivo .wv i {
  width: .16em;
  height: 30%;
  border-radius: 1em;
  background: var(--c1);
}

.uv-ivo .mc {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  position: relative;
  display: grid;
  place-items: center;
  width: 2.9em;
  height: 2.9em;
  border-radius: 50%;
  color: var(--fg);
  background: color-mix(in srgb,var(--fg) 6%,transparent);
  transition: all calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uv-ivo .mc svg {
  width: 1.2em;
  height: 1.2em;
}

.uv-ivo .mc:hover {
  background: color-mix(in srgb,var(--fg) 10%,transparent);
}

.uv-ivo .mc:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uv-ivo .mc::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50%;
  box-shadow: 0 0 0 0 var(--c1);
  opacity: 0;
}

.uv-ivo .st {
  grid-column: 1/-1;
  margin: 0;
  min-height: 1.2em;
  font-size: .75em;
  color: var(--c1);
  font-weight: 600;
}

.uv-ivo.is-rec .mc {
  color: #fff;
  background: var(--c1);
}

.uv-ivo.is-rec .mc::before {
  animation: uv-ivo calc(1.4s / var(--k)) cubic-bezier(.25,.1,.25,1) infinite;
}

.uv-ivo.is-rec .wv {
  opacity: 1;
}

.uv-ivo.is-rec .wv i {
  animation: uv-ivo-w calc(0.9s / var(--k)) ease-in-out infinite;
  animation-delay: calc(var(--i) * calc(-0.11s / var(--k)));
}

@keyframes uv-ivo {
  0% {
    opacity: .5;
    box-shadow: 0 0 0 0 var(--c1);
  }
  100% {
    opacity: 0;
    box-shadow: 0 0 0 .9em var(--c1);
  }
}

@keyframes uv-ivo-w {
  0%,100% {
    height: 20%;
  }
  50% {
    height: 100%;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uv-ivo,.uv-ivo *,.uv-ivo *::before,.uv-ivo *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

