document.querySelectorAll(".uv-ivo").forEach(el => {
  // Demo: escribe una frase de ejemplo. Para dictado real, conecta aquí window.SpeechRecognition.
const i=el.querySelector("input"),m=el.querySelector(".mc"),st=el.querySelector(".st");const PH="Restaurantes con terraza cerca de mí";let t=0,k=0,rec=false;
const stop=()=>{clearTimeout(t);clearInterval(k);rec=false;el.classList.remove("is-rec");m.setAttribute("aria-pressed","false")};
m.addEventListener("click",()=>{if(rec){stop();st.textContent="";return}rec=true;i.value="";el.classList.add("is-rec");m.setAttribute("aria-pressed","true");st.textContent="Escuchando…";
t=setTimeout(()=>{let n=0;k=setInterval(()=>{i.value=PH.slice(0,++n);if(n>=PH.length){stop();st.textContent="Listo";setTimeout(()=>st.textContent="",1500)}},45)},1200)});
return stop
});

