.uvq06-dt {
  --c1: #ea580c;
  --c2: #ffedd5;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq06-dt {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 16em;
}

.uvq06-dt .lb {
  display: block;
  margin: 0 0 .45em;
  font-size: .82em;
  font-weight: 650;
}

.uvq06-dt .fd {
  display: flex;
  align-items: center;
  gap: .1em;
  padding: .45em .7em .45em .45em;
  border-radius: 1em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent),0 14px 34px -24px rgba(0,0,0,.45);
  transition: box-shadow calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-dt .fd:focus-within {
  box-shadow: 0 0 0 2px var(--c1),0 0 0 6px color-mix(in srgb,var(--c1) 18%,transparent),0 14px 34px -24px rgba(0,0,0,.45);
}

.uvq06-dt.bad .fd {
  box-shadow: 0 0 0 2px #e5484d,0 14px 34px -24px rgba(0,0,0,.45);
  animation: uvq06-dt-x calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-dt .pg {
  display: flex;
  flex-direction: column;
  align-items: center;
  flex: none;
  width: 2.5em;
  margin-right: .5em;
  border-radius: .45em;
  overflow: hidden;
  background: var(--bg);
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent),0 .25em .5em -.2em rgba(0,0,0,.3);
  transform-origin: 50% 0;
}

.uvq06-dt .pg.fl {
  animation: uvq06-dt-p calc(0.5s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq06-dt .wd {
  width: 100%;
  padding: .25em 0 .2em;
  font-size: .55em;
  font-weight: 800;
  letter-spacing: .08em;
  text-align: center;
  color: #fff;
  background: var(--c1);
}

.uvq06-dt .dn {
  padding: .05em 0 .12em;
  font-size: 1.15em;
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}

.uvq06-dt .sg {
  box-sizing: content-box;
  width: 1.6em;
  padding: .25em .2em;
  border: 0;
  border-radius: .45em;
  outline: 0;
  background: none;
  font: inherit;
  font-size: 1.2em;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  text-align: center;
  color: var(--fg);
  caret-color: var(--c1);
  transition: background calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1),color calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-dt .sg.y {
  width: 2.75em;
}

.uvq06-dt .sg::placeholder {
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  font-weight: 500;
  letter-spacing: -.03em;
}

.uvq06-dt .sg:hover {
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq06-dt .sg:focus {
  color: var(--c1);
  background: var(--c2);
}

.uvq06-dt .sg.up {
  animation: uvq06-dt-u calc(0.3s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq06-dt .sg.dn {
  animation: uvq06-dt-d calc(0.3s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq06-dt .sp {
  font-size: 1.1em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq06-dt .ft {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  min-height: 1.3em;
  margin: .6em .2em 0;
  font-size: .8em;
}

.uvq06-dt .wn {
  font-weight: 700;
  color: color-mix(in srgb,var(--c1) 70%,var(--fg));
}

.uvq06-dt .wn::first-letter {
  text-transform: uppercase;
}

.uvq06-dt.bad .wn {
  color: #e5484d;
}

.uvq06-dt .wk {
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq06-dt .wk b {
  font-variant-numeric: tabular-nums;
  color: var(--fg);
}

@keyframes uvq06-dt-p {
  0% {
    transform: rotateX(-80deg);
    opacity: .3;
  }
  100% {
    transform: none;
  }
}

@keyframes uvq06-dt-u {
  from {
    transform: translateY(.45em);
    opacity: .2;
  }
}

@keyframes uvq06-dt-d {
  from {
    transform: translateY(-.45em);
    opacity: .2;
  }
}

@keyframes uvq06-dt-x {
  25% {
    transform: translateX(-.25em);
  }
  50% {
    transform: translateX(.25em);
  }
  75% {
    transform: translateX(-.12em);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq06-dt,.uvq06-dt *,.uvq06-dt *::before,.uvq06-dt *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

