document.querySelectorAll(".uvq06-dt").forEach(el => {
  const sg=[...el.querySelectorAll(".sg")],pg=el.querySelector(".pg"),pw=pg.querySelector(".wd"),pd=pg.querySelector(".dn"),wn=el.querySelector(".wn"),wk=el.querySelector(".wk"),wb=wk.querySelector("b");
const W=["domingo","lunes","martes","miércoles","jueves","viernes","sábado"],W3=["DOM","LUN","MAR","MIÉ","JUE","VIE","SÁB"];let last="";
const pad=(s,v)=>String(v).padStart(s.maxLength,"0");
const iso=d=>{const t=new Date(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate()));const n=t.getUTCDay()||7;t.setUTCDate(t.getUTCDate()+4-n);return Math.ceil(((t-Date.UTC(t.getUTCFullYear(),0,1))/864e5+1)/7)};
const u=()=>{const[d,m,y]=sg.map(s=>+s.value);const full=!!(sg[0].value&&sg[1].value&&sg[2].value.length===4);const ok=full&&m>=1&&m<=12&&d>=1&&d<=new Date(y,m,0).getDate();el.classList.toggle("bad",full&&!ok);
if(ok){const dt=new Date(y,m-1,d),k=dt.toDateString();if(k!==last){pg.classList.remove("fl");void pg.offsetWidth;pg.classList.add("fl");last=k}pw.textContent=W3[dt.getDay()];pd.textContent=String(d);wn.textContent=W[dt.getDay()];wk.hidden=false;wb.textContent=String(iso(dt))}else{last="";pw.textContent="···";pd.textContent="?";wn.textContent=full?"Fecha no válida":"";wk.hidden=true}};
const step=(s,dir)=>{const mn=+s.dataset.min,mx=+s.dataset.max;let v=s.value?+s.value+dir:dir>0?mn:mx;if(v>mx)v=mn;if(v<mn)v=mx;s.value=pad(s,v);s.classList.remove("up","dn");void s.offsetWidth;s.classList.add(dir>0?"up":"dn");s.select();u()};
const go=k=>{if(sg[k]){sg[k].focus();sg[k].select()}};
sg.forEach((s,k)=>{s.addEventListener("keydown",e=>{const sep=e.key==="/"||e.key==="."||e.key==="-";
if(e.key==="ArrowUp"||e.key==="ArrowDown"){e.preventDefault();step(s,e.key==="ArrowUp"?1:-1)}
else if(sep||e.key==="ArrowRight"&&s.selectionStart===s.value.length&&sg[k+1]){e.preventDefault();go(k+1)}
else if((e.key==="ArrowLeft"&&s.selectionEnd===0||e.key==="Backspace"&&!s.value)&&sg[k-1]){e.preventDefault();go(k-1)}});
s.addEventListener("input",()=>{s.value=s.value.replace(/\D/g,"").slice(0,s.maxLength);const v=+s.value;if(sg[k+1]&&(s.value.length===s.maxLength||k===0&&v>3||k===1&&v>1)){s.value=pad(s,v);go(k+1)}u()});
s.addEventListener("focus",()=>s.select());
s.addEventListener("blur",()=>{if(s.value&&k<2&&s.value.length<2)s.value=pad(s,+s.value);u()})});
const n=new Date();sg[0].value=pad(sg[0],n.getDate());sg[1].value=pad(sg[1],n.getMonth()+1);sg[2].value=String(n.getFullYear());u()
});

