.uvq06-ml {
  --c1: #4338ca;
  --c2: #e0e7ff;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq06-ml {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 20em;
}

.uvq06-ml .tx {
  margin: 0;
  font: 400 1.3em/2 Georgia,"Iowan Old Style","Times New Roman",serif;
  letter-spacing: -.005em;
  text-wrap: pretty;
}

.uvq06-ml .w {
  position: relative;
  display: inline-block;
}

.uvq06-ml input,.uvq06-ml select {
  box-sizing: border-box;
  width: 6.5em;
  min-width: 3ch;
  max-width: 14em;
  field-sizing: content;
  margin: 0;
  padding: 0 .12em;
  border: 0;
  border-bottom: 2px dashed color-mix(in srgb,var(--fg) 55%,transparent);
  border-radius: .2em .2em 0 0;
  outline: 0;
  background: none;
  font: inherit;
  font-style: italic;
  color: color-mix(in srgb,var(--c1) 70%,var(--fg));
  transition: border-color calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1),background calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-ml input::placeholder {
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq06-ml input:not(:placeholder-shown) {
  font-style: normal;
  border-bottom-style: solid;
  border-bottom-color: var(--c1);
}

.uvq06-ml input:hover,.uvq06-ml select:hover {
  background: color-mix(in srgb,var(--fg) 6%,transparent);
}

.uvq06-ml input:focus,.uvq06-ml select:focus {
  border-bottom-style: solid;
  border-bottom-color: var(--c1);
  background: color-mix(in srgb,var(--c1) 14%,transparent);
}

.uvq06-ml select {
  width: auto;
  -webkit-appearance: none;
  appearance: none;
  padding-right: 1.1em;
  font-style: normal;
  border-bottom-style: solid;
  border-bottom-color: var(--c1);
  cursor: pointer;
  field-sizing: content;
}

.uvq06-ml select option {
  color: #111;
  background: #fff;
}

.uvq06-ml .sl::after {
  content: "";
  position: absolute;
  right: .2em;
  top: 52%;
  width: .32em;
  height: .32em;
  border-right: 2px solid var(--c1);
  border-bottom: 2px solid var(--c1);
  transform: translateY(-70%) rotate(45deg);
  pointer-events: none;
}

.uvq06-ml .mr {
  position: absolute;
  left: 0;
  top: 0;
  padding: 0 .12em;
  visibility: hidden;
  white-space: pre;
  font: inherit;
  pointer-events: none;
}

.uvq06-ml .w.no {
  animation: uvq06-ml calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-ml .w.no input {
  border-bottom-color: #e5484d;
}

.uvq06-ml .go {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  display: inline-flex;
