}

.uvq06-ml .go span {
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq06-ml .go:hover {
  transform: translateY(-2px);
}

.uvq06-ml .go:hover span {
  transform: translateX(.25em);
}

.uvq06-ml .go:active {
  transform: scale(.96);
}

.uvq06-ml .go:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq06-ml .ok {
  min-height: 1.2em;
