  const out=el.querySelector(".out"),i=el.querySelector("input"),f=el.querySelector("form");const C=["help","ls","date","whoami","echo","clear"],H=[];let h=0;
const line=(t,c)=>{const p=document.createElement("p");if(c)p.className=c;p.textContent=t;out.append(p);while(out.children.length>40)out.firstChild.remove();out.scrollTop=out.scrollHeight};
const echo=t=>{const p=document.createElement("p"),b=document.createElement("b");b.textContent="~/web ❯ ";p.append(b,t);out.append(p)};
const R={help:()=>"Órdenes: "+C.join(", "),ls:()=>"index.html  estilos.css  app.js  img/",date:()=>new Date().toLocaleString(),whoami:()=>"invitado",echo:a=>a.join(" ")};
