.uvq06-pl {
  --c1: #003399;
  --c2: #ffcc00;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq06-pl {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 17em;
  perspective: 40em;
}

.uvq06-pl .lb {
  display: block;
  margin: 0 0 .45em;
  font-size: .82em;
  font-weight: 650;
}

.uvq06-pl .pt {
  position: relative;
  display: flex;
  height: 3.6em;
  border-radius: .5em;
  overflow: hidden;
  background: linear-gradient(170deg,#fff,#f1f1ec);
  box-shadow: inset 0 0 0 .12em #1a1a1a,0 0 0 .22em #c9ced4,0 0 0 calc(.22em + 1px) #8d939b,0 .9em 1.4em -.8em rgba(0,0,0,.6);
  transition: transform calc(0.5s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq06-pl .pt:hover {
  transform: rotateX(10deg) rotateY(-8deg);
}

.uvq06-pl .pt:has(input:focus-visible) {
  outline: 2px solid color-mix(in srgb,var(--c1) 60%,var(--fg));
  outline-offset: .45em;
}

.uvq06-pl .pt::after {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(105deg,transparent 35%,rgba(255,255,255,.85) 50%,transparent 65%);
  transform: translateX(-120%);
  pointer-events: none;
}

.uvq06-pl.ok .pt::after {
  animation: uvq06-pl calc(0.9s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-pl .eu {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: space-between;
  flex: none;
  width: 2em;
  margin: .12em 0 .12em .12em;
  padding: .32em 0 .28em;
  border-radius: .38em 0 0 .38em;
  color: #fff;
  background: var(--c1);
}

.uvq06-pl .eu svg {
  width: 1.55em;
  height: 1.55em;
  fill: var(--c2);
}

.uvq06-pl .eu b {
  font-size: .95em;
  font-weight: 800;
  line-height: 1;
}

.uvq06-pl input {
  flex: 1;
  min-width: 0;
  margin: 0;
  padding: 0 .2em;
  border: 0;
  outline: 0;
  background: none;
  text-align: center;
  font: 700 2.05em/1 "DIN Condensed","Arial Narrow","Roboto Condensed","Helvetica Neue",Arial,sans-serif;
  font-stretch: condensed;
  letter-spacing: .06em;
  text-transform: uppercase;
  color: #111;
  caret-color: var(--c1);
}

.uvq06-pl input::placeholder {
  color: rgba(17,17,17,.16);
}

.uvq06-pl .ht {
  min-height: 1.2em;
  margin: .8em 0 0;
  font-size: .75em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
  transition: color calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-pl.ok .ht {
  font-weight: 650;
  color: #16a34a;
}

.uvq06-pl.warn .ht {
  font-weight: 650;
  color: #e5484d;
}

.uvq06-pl.warn .pt {
  animation: uvq06-pl-x calc(0.35s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

@keyframes uvq06-pl {
  to {
    transform: translateX(120%);
  }
}

@keyframes uvq06-pl-x {
  25% {
    translate: -.2em 0;
  }
  50% {
    translate: .2em 0;
  }
  75% {
    translate: -.1em 0;
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq06-pl,.uvq06-pl *,.uvq06-pl *::before,.uvq06-pl *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

