.uvq06-cp {
  --c1: #db2777;
  --c2: #fce7f3;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq06-cp {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  position: relative;
  width: 19em;
}

.uvq06-cp .tk {
  display: grid;
  grid-template-columns: 4.4em minmax(0,1fr);
  filter: drop-shadow(0 .7em .9em rgba(0,0,0,.18));
}

.uvq06-cp .sb {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: .25em;
  border-radius: .8em 0 0 .8em;
  color: #fff;
  background: radial-gradient(circle at 30% 20%,rgba(255,255,255,.28),transparent 60%),var(--c1);
  -webkit-mask: radial-gradient(circle at 100% 0,#0000 .5em,#000 calc(.5em + .5px)) top/100% 51% no-repeat,radial-gradient(circle at 100% 100%,#0000 .5em,#000 calc(.5em + .5px)) bottom/100% 51% no-repeat;
  mask: radial-gradient(circle at 100% 0,#0000 .5em,#000 calc(.5em + .5px)) top/100% 51% no-repeat,radial-gradient(circle at 100% 100%,#0000 .5em,#000 calc(.5em + .5px)) bottom/100% 51% no-repeat;
  transform-origin: 100% 100%;
  transition: transform calc(0.8s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.6s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-cp .sb b {
  font-size: 2em;
  font-weight: 900;
  line-height: 1;
}

.uvq06-cp .sb span {
  font-size: .6em;
  font-weight: 800;
  letter-spacing: .14em;
  text-transform: uppercase;
}

.uvq06-cp .mn {
  padding: .85em 1em .75em 1.1em;
  border-left: 2px dashed color-mix(in srgb,var(--c1) 45%,transparent);
  border-radius: 0 .8em .8em 0;
  background: color-mix(in srgb,var(--c1) 7%,var(--bg));
  -webkit-mask: radial-gradient(circle at 0 0,#0000 .5em,#000 calc(.5em + .5px)) top/100% 51% no-repeat,radial-gradient(circle at 0 100%,#0000 .5em,#000 calc(.5em + .5px)) bottom/100% 51% no-repeat;
  mask: radial-gradient(circle at 0 0,#0000 .5em,#000 calc(.5em + .5px)) top/100% 51% no-repeat,radial-gradient(circle at 0 100%,#0000 .5em,#000 calc(.5em + .5px)) bottom/100% 51% no-repeat;
}

.uvq06-cp label {
  display: block;
  margin: 0 0 .45em;
  font-size: .68em;
  font-weight: 800;
  letter-spacing: .1em;
  text-transform: uppercase;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq06-cp .rw {
  display: flex;
  gap: .35em;
  padding: .25em;
  border-radius: .7em;
  background: var(--bg);
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent);
  transition: box-shadow calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-cp .rw:focus-within {
  box-shadow: 0 0 0 2px var(--c1),0 0 0 5px color-mix(in srgb,var(--c1) 18%,transparent);
}

.uvq06-cp input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  font: inherit;
  color: var(--fg);
  width: 0;
  height: 2.3em;
  padding: 0 .5em;
  font-family: ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  font-weight: 700;
  letter-spacing: .12em;
  text-transform: uppercase;
}

.uvq06-cp input::placeholder {
  letter-spacing: .06em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq06-cp button {
  font: inherit;
  color: inherit;
  border: 0;
  margin: 0;
  background: none;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  padding: 0 .9em;
  border-radius: .5em;
  font-size: .85em;
  font-weight: 750;
  color: #fff;
  background: var(--c1);
  transition: transform calc(0.25s / var(--k)) cubic-bezier(.34,1.56,.64,1),filter calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-cp button:hover {
  filter: brightness(1.1);
}

.uvq06-cp button:active {
  transform: scale(.94);
}

.uvq06-cp button:focus-visible {
  outline: 2px solid var(--c1);
  outline-offset: 3px;
}

.uvq06-cp .ms {
  min-height: 1.2em;
  margin: .5em 0 0;
  font-size: .75em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq06-cp.no .mn {
  animation: uvq06-cp-x calc(0.45s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-cp.no .ms {
  font-weight: 650;
  color: #e5484d;
}

.uvq06-cp.ok .ms {
  font-weight: 650;
  color: color-mix(in srgb,var(--c1) 70%,var(--fg));
}

.uvq06-cp.ok .sb {
  transform: translate(-.5em,1.6em) rotate(-26deg);
  opacity: 0;
}

.uvq06-cp .stp {
  position: absolute;
  left: .1em;
  top: 50%;
  padding: .25em .4em;
  border: .16em solid var(--c1);
  border-radius: .4em;
  font-size: 1.05em;
  font-weight: 900;
  letter-spacing: -.02em;
  white-space: nowrap;
  color: var(--c1);
  opacity: 0;
  transform: translateY(-50%) rotate(-14deg) scale(2.4);
  pointer-events: none;
}

.uvq06-cp.ok .stp {
  animation: uvq06-cp-s calc(0.45s / var(--k)) cubic-bezier(.34,1.56,.64,1) calc(0.3s / var(--k)) both;
}

@keyframes uvq06-cp-s {
  from {
    opacity: 0;
    transform: translateY(-50%) rotate(-14deg) scale(2.4);
  }
  to {
    opacity: 1;
    transform: translateY(-50%) rotate(-14deg) scale(1);
  }
}

@keyframes uvq06-cp-x {
  25% {
    transform: translateX(-.25em) rotate(-1deg);
  }
  50% {
    transform: translateX(.25em) rotate(1deg);
  }
  75% {
    transform: translateX(-.1em);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq06-cp,.uvq06-cp *,.uvq06-cp *::before,.uvq06-cp *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

