document.querySelectorAll(".uvq06-mn").forEach(el => {
  const ta=el.querySelector("textarea"),ls=el.querySelector("ul"),bk=el.querySelector(".bk"),os=[...ls.children];let q=null,act=0,vis=[];
const RE=new RegExp("@("+os.map(o=>o.dataset.n).join("|")+")","g");
const norm=s=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
const paint=()=>{bk.innerHTML=ta.value.replace(/[&<>]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;"})[c]).replace(RE,"<mark>$&</mark>")+"\n ";bk.scrollTop=ta.scrollTop};
const at=()=>{const v=ta.value.slice(0,ta.selectionStart),m=v.match(/(^|\s)@([\p{L}]*)$/u);return m?{s:v.length-m[2].length-1,q:m[2]}:null};
const close=()=>{ls.hidden=true;ta.setAttribute("aria-expanded","false");ta.removeAttribute("aria-activedescendant");act=0};
const mark=()=>{os.forEach(o=>o.setAttribute("aria-selected",String(o===vis[act])));if(vis[act])ta.setAttribute("aria-activedescendant",vis[act].id)};
const show=()=>{q=at();vis=q?os.filter(o=>norm(o.dataset.n).includes(norm(q.q))):[];os.forEach(o=>o.hidden=!vis.includes(o));if(!vis.length)return close();ls.hidden=false;ta.setAttribute("aria-expanded","true");act=Math.min(act,vis.length-1);mark()};
const pick=o=>{if(!q)return;const n="@"+o.dataset.n+" ",a=ta.value.slice(0,q.s),b=ta.value.slice(ta.selectionStart);ta.value=a+n+b;const p=a.length+n.length;ta.focus();ta.setSelectionRange(p,p);close();paint()};
ta.addEventListener("input",()=>{paint();show()});
ta.addEventListener("keydown",e=>{if(ls.hidden)return;if(e.key==="ArrowDown"||e.key==="ArrowUp"){e.preventDefault();act=(act+(e.key==="ArrowDown"?1:-1)+vis.length)%vis.length;mark()}else if(e.key==="Enter"||e.key==="Tab"){e.preventDefault();pick(vis[act])}else if(e.key==="Escape"){e.preventDefault();close()}});
ta.addEventListener("scroll",()=>{bk.scrollTop=ta.scrollTop});ta.addEventListener("blur",close);ta.addEventListener("click",show);
ls.addEventListener("pointerdown",e=>e.preventDefault());
os.forEach(o=>{o.addEventListener("click",()=>pick(o));o.addEventListener("pointermove",()=>{const k=vis.indexOf(o);if(k>-1&&k!==act){act=k;mark()}})});
ta.value="Buen trabajo, @Marta Ruiz. ¿Lo revisamos mañana con ";paint()
});

