.uvq06-lt {
  --c1: #b91c1c;
  --c2: #334155;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq06-lt {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 19em;
}

.uvq06-lt .sr {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}

.uvq06-lt .dv {
  position: relative;
  display: flex;
  align-items: center;
  gap: .7em;
  padding: 1em .8em .8em .9em;
  border-radius: 1.1em 2.4em 2.4em 1.1em;
  background: linear-gradient(160deg,color-mix(in srgb,var(--c2) 80%,#fff),var(--c2) 45%,color-mix(in srgb,var(--c2) 70%,#000));
  box-shadow: inset 0 1px 0 rgba(255,255,255,.25),inset 0 -.2em 0 rgba(0,0,0,.25),0 1em 1.6em -.9em rgba(0,0,0,.6);
}

.uvq06-lt.go .dv {
  animation: uvq06-lt-v calc(0.9s / var(--k)) steps(9);
}

.uvq06-lt.no .lcd {
  animation: uvq06-lt-x calc(0.4s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-lt .br {
  position: absolute;
  left: 1.6em;
  top: .45em;
  font: 800 .5em/1 ui-monospace,"SF Mono",Menlo,Consolas,monospace;
  letter-spacing: .24em;
  color: rgba(255,255,255,.55);
