  box-shadow: inset 0 .12em .25em rgba(0,0,0,.4),0 0 0 .18em rgba(0,0,0,.35);
  transition: box-shadow calc(0.2s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-lt .lcd:focus-within {
  box-shadow: inset 0 .12em .25em rgba(0,0,0,.4),0 0 0 .18em rgba(0,0,0,.35),0 0 0 .38em #fff;
