  text-shadow: 0 -1px 0 rgba(0,0,0,.4),0 1px 0 rgba(255,255,255,.35);
  background: linear-gradient(color-mix(in srgb,var(--c1) 78%,#fff),var(--c1) 30%,var(--c1) 70%,color-mix(in srgb,var(--c1) 72%,#000));
  clip-path: polygon(.45em 0,100% 0,calc(100% - .45em) 100%,0 100%);
  rotate: var(--r,0deg);
  transition: transform calc(0.3s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq06-lt .tp button:hover {
  transform: translateY(-2px);
}

.uvq06-lt .tp li.in button {
  animation: uvq06-lt calc(0.9s / var(--k)) steps(9);
}

.uvq06-lt .tp li.pe {
  animation: uvq06-lt-p calc(0.5s / var(--k)) cubic-bezier(.25,.1,.25,1) forwards;
}

.uvq06-lt .ht {
  margin: .5em 0 0;
  font-size: .74em;
