.uvq06-ad {
  --c1: #e11d48;
  --c2: #4ade80;
  --s: 16px;
  /* tamaño */
  --k: 1;
  /* velocidad */
  --fg: #1d1d1f;
  /* texto */
  --bg: #f5f5f7;
  /* fondo */
}

.uvq06-ad {
  font-family: -apple-system,BlinkMacSystemFont,"SF Pro Text","Inter",system-ui,sans-serif;
  font-size: var(--s);
  color: var(--fg);
  -webkit-tap-highlight-color: transparent;
  width: 19em;
}

.uvq06-ad .lb {
  display: block;
  margin: 0 0 .45em;
  font-size: .82em;
  font-weight: 650;
}

.uvq06-ad .fd {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: .55em;
  padding: 0 .85em;
  border-radius: .9em;
  background: color-mix(in srgb,var(--fg) 3%,var(--bg));
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent),0 14px 34px -24px rgba(0,0,0,.45);
  transition: box-shadow calc(0.25s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-ad .fd:focus-within {
  box-shadow: 0 0 0 2px var(--c1),0 0 0 6px color-mix(in srgb,var(--c1) 18%,transparent),0 14px 34px -24px rgba(0,0,0,.45);
}

.uvq06-ad .fd>svg {
  flex: none;
  width: 1.15em;
  height: 1.15em;
  color: var(--c1);
}

.uvq06-ad input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: none;
  font: inherit;
  color: var(--fg);
  height: 2.8em;
}

.uvq06-ad input::placeholder {
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq06-ad ul {
  position: absolute;
  left: 0;
  right: 0;
  top: calc(100% + .35em);
  margin: 0;
  padding: .3em;
  list-style: none;
  border-radius: .9em;
  background: var(--bg);
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent),0 1em 2em -.8em rgba(0,0,0,.45);
  transform-origin: 50% 0;
  animation: uvq06-ad-l calc(0.22s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq06-ad [hidden] {
  display: none!important;
}

.uvq06-ad li {
  display: grid;
  gap: .1em;
  padding: .42em .6em;
  border-radius: .6em;
  cursor: pointer;
}

.uvq06-ad li[aria-selected="true"] {
  background: color-mix(in srgb,var(--c1) 12%,transparent);
}

.uvq06-ad li b {
  font-size: .86em;
  font-weight: 650;
}

.uvq06-ad li span {
  font-size: .7em;
  color: color-mix(in srgb,var(--fg) 55%,transparent);
}

.uvq06-ad .mp {
  position: relative;
  height: 7.6em;
  margin-top: .7em;
  border-radius: 1em;
  overflow: hidden;
  box-shadow: 0 0 0 1px color-mix(in srgb,var(--fg) 12%,transparent);
}

.uvq06-ad svg {
  display: block;
  width: 100%;
  height: 100%;
  transform-origin: var(--x,50%) var(--y,50%);
  scale: var(--z,1);
  transition: scale calc(0.9s / var(--k)) cubic-bezier(.22,1,.36,1),transform-origin calc(0.9s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq06-ad .ld {
  fill: color-mix(in srgb,var(--fg) 5%,var(--bg));
}

.uvq06-ad .pk {
  fill: color-mix(in srgb,var(--c2) 30%,var(--bg));
}

.uvq06-ad .rv {
  fill: none;
  stroke: color-mix(in srgb,#38bdf8 35%,var(--bg));
  stroke-width: 7;
}

.uvq06-ad .s1,.uvq06-ad .s2 {
  fill: none;
  stroke: color-mix(in srgb,var(--fg) 15%,var(--bg));
}

.uvq06-ad .s1 {
  stroke-width: 4.5;
  stroke: color-mix(in srgb,var(--fg) 20%,var(--bg));
}

.uvq06-ad .s2 {
  stroke-width: 2;
}

.uvq06-ad .pin {
  position: absolute;
  left: var(--x,50%);
  top: var(--y,50%);
  width: 1.5em;
  height: 1.5em;
  margin: -1.75em 0 0 -.75em;
  opacity: 0;
  filter: drop-shadow(0 .3em .2em rgba(0,0,0,.3));
  transition: left calc(0.7s / var(--k)) cubic-bezier(.22,1,.36,1),top calc(0.7s / var(--k)) cubic-bezier(.22,1,.36,1),opacity calc(0.3s / var(--k)) cubic-bezier(.25,.1,.25,1);
}

.uvq06-ad .pin::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: 50% 50% 50% 0;
  background: var(--c1);
  rotate: -45deg;
}

.uvq06-ad .pin::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  width: .5em;
  height: .5em;
  margin: -.25em;
  border-radius: 50%;
  background: #fff;
}

.uvq06-ad.has .pin {
  opacity: 1;
}

.uvq06-ad .pin.drop {
  animation: uvq06-ad calc(0.6s / var(--k)) cubic-bezier(.34,1.56,.64,1);
}

.uvq06-ad .rp {
  position: absolute;
  left: var(--x,50%);
  top: var(--y,50%);
  width: 2.6em;
  height: 1em;
  margin: -.5em 0 0 -1.3em;
  border: 2px solid var(--c1);
  border-radius: 50%;
  opacity: 0;
  transition: left calc(0.7s / var(--k)) cubic-bezier(.22,1,.36,1),top calc(0.7s / var(--k)) cubic-bezier(.22,1,.36,1);
}

.uvq06-ad .rp.go {
  animation: uvq06-ad-r calc(0.9s / var(--k)) cubic-bezier(.25,.1,.25,1) calc(0.4s / var(--k));
}

.uvq06-ad .ok {
  min-height: 1.2em;
  margin: .5em 0 0;
  font-size: .76em;
  font-weight: 650;
  color: #16a34a;
}

@keyframes uvq06-ad {
  from {
    transform: translateY(-1.8em);
    opacity: 0;
  }
}

@keyframes uvq06-ad-r {
  0% {
    opacity: .9;
    transform: scale(.3);
  }
  100% {
    opacity: 0;
    transform: scale(1.9);
  }
}

@keyframes uvq06-ad-l {
  from {
    opacity: 0;
    transform: translateY(-.3em) scale(.97);
  }
}

@media (prefers-reduced-motion:reduce) {
  .uvq06-ad,.uvq06-ad *,.uvq06-ad *::before,.uvq06-ad *::after {
    animation-duration: .01ms!important;
    animation-iteration-count: 1!important;
    transition-duration: .01ms!important;
  }
}

