document.querySelectorAll(".uvq06-ad").forEach(el => {
  const i=el.querySelector("input"),ls=el.querySelector("ul"),os=[...ls.children],mp=el.querySelector(".mp"),pin=el.querySelector(".pin"),rp=el.querySelector(".rp"),ok=el.querySelector(".ok");let act=0,vis=[];
const norm=s=>s.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLowerCase();
const mark=()=>{os.forEach(o=>o.setAttribute("aria-selected",String(o===vis[act])));if(vis[act])i.setAttribute("aria-activedescendant",vis[act].id)};
const close=()=>{ls.hidden=true;i.setAttribute("aria-expanded","false");i.removeAttribute("aria-activedescendant")};
const open=()=>{const q=norm(i.value.trim());vis=os.filter(o=>!q||norm(o.textContent).includes(q));os.forEach(o=>o.hidden=!vis.includes(o));if(!vis.length)return close();ls.hidden=false;i.setAttribute("aria-expanded","true");act=0;mark()};
const pick=o=>{i.value=o.querySelector("b").textContent+", Madrid";close();mp.style.setProperty("--x",o.dataset.x+"%");mp.style.setProperty("--y",o.dataset.y+"%");mp.style.setProperty("--z","1.35");pin.classList.remove("drop");rp.classList.remove("go");void pin.offsetWidth;pin.classList.add("drop");rp.classList.add("go");el.classList.add("has");ok.textContent="Reparto disponible en esta zona"};
i.addEventListener("input",()=>{el.classList.remove("has");ok.textContent="";mp.style.setProperty("--z","1");open()});
i.addEventListener("focus",open);i.addEventListener("blur",close);
i.addEventListener("keydown",e=>{if(ls.hidden){if(e.key==="ArrowDown"){e.preventDefault();open()}return}if(e.key==="ArrowDown"||e.key==="ArrowUp"){e.preventDefault();act=(act+(e.key==="ArrowDown"?1:-1)+vis.length)%vis.length;mark()}else if(e.key==="Enter"){e.preventDefault();pick(vis[act])}else if(e.key==="Escape"){e.preventDefault();close()}});
ls.addEventListener("pointerdown",e=>e.preventDefault());
os.forEach(o=>{o.addEventListener("click",()=>pick(o));o.addEventListener("pointermove",()=>{const k=vis.indexOf(o);if(k>-1&&k!==act){act=k;mark()}})});
pick(os[0])
});

