const sync=()=>{hi.scrollTop=gt.scrollTop=ta.scrollTop;hi.scrollLeft=ta.scrollLeft;el.style.setProperty("--st",ta.scrollTop+"px")};
const draw=()=>{hi.innerHTML=H(ta.value)+"\n ";const n=ta.value.split("\n").length,b=ta.value.slice(0,ta.selectionStart).split("\n"),ln=b.length-1;gt.innerHTML=Array.from({length:n},(_,k)=>"<span"+(k===ln?' class="on"':"")+">"+(k+1)+"</span>").join("");el.style.setProperty("--ln",String(ln));ps.textContent="Ln "+(ln+1)+", Col "+(b[ln].length+1);sync()};
const ins=(t,back)=>{ta.setRangeText(t,ta.selectionStart,ta.selectionEnd,"end");if(back)ta.selectionStart=ta.selectionEnd=ta.selectionEnd-back;draw()};
const P={"{":"}","(":")","[":"]",'"':'"'};
ta.addEventListener("keydown",e=>{if(e.key==="Escape"){esc=true;return}if(e.key==="Tab"){if(esc){esc=false;return}e.preventDefault();ins("  ");return}esc=false;if(e.ctrlKey||e.metaKey||e.altKey)return;
const nx=ta.value[ta.selectionStart];if((e.key==="}"||e.key===")"||e.key==="]"||e.key==='"')&&nx===e.key&&ta.selectionStart===ta.selectionEnd){e.preventDefault();ta.selectionStart=ta.selectionEnd=ta.selectionStart+1;draw();return}
if(Object.prototype.hasOwnProperty.call(P,e.key)){e.preventDefault();ins(e.key+P[e.key],1);return}
if(e.key==="Enter"){e.preventDefault();const s=ta.selectionStart,ind=ta.value.slice(0,s).split("\n").pop().match(/^\s*/)[0],o=ta.value[s-1]==="{";if(o&&nx==="}")ins("\n"+ind+"  \n"+ind,ind.length+1);else ins("\n"+ind+(o?"  ":""))}});
