ta.value=["/* Botón principal */",".btn {","  color: #fff;","  padding: 0.8em 1.6em;","  border-radius: 999px;","}"].join("\n");draw()
}

export default function InCodeEditor() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
